  OXTR: { headline: "A/G — Heterozygota (Pośrednia)", impact: "Fenotyp Modulowany: Profil wykazujący pośrednie wartości neurofizjologiczne. W wielu analizach medycznych wystarczy jednak obecność jednej kopii allelu A, by wykazać osłabione mechanizmy buforowania wsparcia. Jednostki te dysponują umiarkowanymi wynikami empatycznymi w populacji ogólnej bez drastycznych wahań.", toneCtx: { heading: "rs53576 (3'-UTR — receptor oksytocyny)", genotype: "A/G" }, variants: [{ headline: "A/G — Heterozygota (Pośrednia)", text: "Fenotyp Modulowany: Profil wykazujący pośrednie wartości neurofizjologiczne. W wielu analizach medycznych wystarczy jednak obecność jednej kopii allelu A, by wykazać osłabione mechanizmy buforowania wsparcia. Jednostki te dysponują umiarkowanymi wynikami empatycznymi w populacji ogólnej bez drastycznych wahań.", heading: "rs53576 (3'-UTR — receptor oksytocyny)", genotype: "A/G" }], byTopic: { asd: { variants: [{ headline: "A/G — Heterozygota (Pośrednia)", text: "Kofaktory – Magnez (Mg2+) i Witamina D: Jony magnezu są absolutnie konieczne, by receptor OXT zachował konformację umożliwiającą przyłączanie hormonu i skutecznie hamował pobudliwość neuronów (hiperpolaryzacja). Dodatkowo podaż witaminy D bezpośrednio aktywuje transkrypcję z obszaru OXTR w jądrze, potęgując pulę receptorów i hormonu w ciele migdałowatym.", heading: "rs53576 (3'-UTR — receptor oksytocyny)", genotype: "A/G" }] }, folate: { variants: [{ headline: "A/G — Heterozygota (Pośrednia)", text: "Styl życia: Aktywacja rzutów oksytocyny może być samodzielnie wspomagana bez chemii. Somatyczne wyzwalanie układu aferentnego przy pomocy powięziowego masażu ucisku, regularnej jogi, wspólnego śpiewu i kontaktów z psami skutecznie podnosi podwzgórzową stymulację wolnego OXT u pacjentów.", heading: "rs53576 (3'-UTR — receptor oksytocyny)", genotype: "A/G" }] }, psychopharm: { variants: [{ headline: "A/G — Heterozygota (Pośrednia)", text: "Rewolucja na osi Mikrobiom-Mózg: Niewątpliwym sukcesem neurobiologicznym jest wpływ specyficznego probiotyku Lactobacillus reuteri (ATCC-PTA-6475) wyizolowanego z mleka. Bakteria ta drastycznie stymuluje i uwalnia endogenną oksytocynę w mózgu omijając zjawiska odpornościowe komórek limfocytów. Wykorzystuje ona bezpośrednio połączenia wstępujące włókien nerwu błędnego u naczelnych, rewelacyjnie rewersując deficyty beh…", heading: "rs53576 (3'-UTR — receptor oksytocyny)", genotype: "A/G" }] }, substances: { variants: [{ headline: "A/G — Heterozygota (Pośrednia)", text: "Używki a zdrowie wątroby: U układów pozbawionych barier (jak profil GG z wysoką korelacją prospołeczności), wykazano wysoce niezależny od ogólnego spożycia cukru pęd ku nawykowej konsumpcji mocnych form ujęć nagradzających (cukru i etanolu). Kobiety z homozygotą G/G są mocno dysponowane do ciężkich, uogólnionych schorzeń stłuszczeniowych wątroby z obu grup ryzyk (MASLD/ALD), co wymaga ostrego nadzoru prób wątrobowych…", heading: "rs53576 (3'-UTR — receptor oksytocyny)", genotype: "A/G" }] } } },
